using System; using System.Collections.Generic; using System.Diagnostics; using System.Drawing; using System.IO; using System.Linq; using System.Net; using System.Text; using System.Text.RegularExpressions; using System.Windows.Forms;
internal static class CreatureAnimationStudio {
 [STAThread] static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new App());}
 sealed class Room { public string Id,Name,Photo,Theme; public override string ToString(){return Name;} }
 sealed class Item { public string Title,Key,Text; public override string ToString(){return Title;} }
 sealed class App:Form {
  readonly string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"CreatureAnimationStudio"); readonly List<Room> rooms=new List<Room>(); readonly Random r=new Random();
  readonly string[] places={"a miniature omakase bar","a cozy magical bakery","a moonlit flower garden","a sparkling seaside market","a tiny fantasy kitchen"}; readonly string[] props={"strawberry macaron: two small round rose-pink almond shells, pale strawberry cream filling, one tiny strawberry slice","grape cotton candy: a large airy purple sugar cloud on a paper stick, wispy spun-sugar threads, translucent sugar crystals","blue lemon cotton candy: a cloud-light cotton candy with soft sky-blue and pale lemon swirls, sparkling sugar grains","peach jelly: a translucent peach-pink dome with a glossy surface, tiny green leaf, soft wobble","blueberry tart: a bite-sized golden tart shell, vanilla cream, glossy whole blueberries","vanilla ice cream: one ivory scoop in a crisp waffle cup, tiny vanilla bean specks, slowly melting edge","lemon cream mochi: a round white rice-dough pouch, pale-yellow lemon cream center, powdery soft surface","mango mousse cake: a small sunny-yellow cube cake, white cream layers, glossy mango cube topping","chocolate lava cookie: a warm cracked cocoa cookie with slow molten chocolate center","matcha dorayaki: two soft green tea pancakes with dark red-bean filling visible at the edge","raspberry donut: a small pink-glazed ring donut with raspberry sugar dust and a soft cake crumb","honey butter toast: a tiny golden toast cube with melting butter, glossy honey drizzle and crisp edges","rainbow fruit candy: a clear hard candy sphere with tiny colorful fruit layers trapped inside","pistachio gelato: a pale green scoop with crushed pistachio pieces in a miniature cone","cherry cheesecake: a small white cheesecake slice with a ruby cherry sauce swirl","caramel popcorn: a tiny striped cup filled with golden caramel-coated popped kernels","strawberry milk pudding: a pale pink wobbling pudding cup with red strawberry sauce layer","yuzu soda float: a clear glass of fizzy yuzu soda, ice cubes and a small vanilla scoop","black sesame cookie: a charcoal-gray crumbly cookie with black sesame speckles and cream center","watermelon sorbet: a small red-and-green melon-shaped sorbet scoop with tiny dark seed chips","lavender marshmallow: two puffy pale-lilac marshmallows dusted with sugar","cinnamon roll: a miniature spiral bun with cinnamon ribbons and glossy cream icing","lychee crystal jelly: a transparent milky jelly sphere with a pink lychee center","tangerine tartlet: a golden tartlet topped with tiny orange segments and citrus glaze"}; readonly string[] actions={"discovers","carefully investigates","tries to prepare","gently tastes","plays with"}; readonly string[] endings={"does a happy spin","waves toward the camera","tilts its head with delight","makes a gentle final jump"};
  Panel page; Room current; ListBox roomList,archive; TextBox theme,result,revision,directPrompt; PictureBox photo; Label photoLabel;
  public App(){Directory.CreateDirectory(root);Text="Creature Animation Prompt Studio";Size=new Size(1220,790);MinimumSize=new Size(900,620);BackColor=Color.FromArgb(246,249,253);Font=new Font("Malgun Gothic",10);LoadRooms();ShowHome();}
  string RoomsFile{get{return Path.Combine(root,"rooms.dat");}} string VideoRoomFile{get{return Path.Combine(root,"food-video-room.txt");}} string ArchiveFile{get{return Path.Combine(root,"archive-"+current.Id+".dat");}} string E(string s){return Convert.ToBase64String(Encoding.UTF8.GetBytes(s??""));} string D(string s){try{return Encoding.UTF8.GetString(Convert.FromBase64String(s));}catch{return "";}}
  void LoadRooms(){if(File.Exists(RoomsFile))foreach(var x in File.ReadAllLines(RoomsFile)){var p=x.Split('|');if(p.Length==4)rooms.Add(new Room{Id=p[0],Name=D(p[1]),Photo=D(p[2]),Theme=D(p[3])});}if(!File.Exists(VideoRoomFile)&&rooms.Count>0)File.WriteAllText(VideoRoomFile,rooms[0].Id);}
  void SaveRooms(){File.WriteAllLines(RoomsFile,rooms.Select(x=>x.Id+"|"+E(x.Name)+"|"+E(x.Photo)+"|"+E(x.Theme)));}
  void SetPage(Control c){if(page!=null)Controls.Remove(page);page=new Panel{Dock=DockStyle.Fill,Padding=new Padding(32),BackColor=BackColor};page.Controls.Add(c);Controls.Add(page);}
  Label Title(string s){return new Label{Text=s,Dock=DockStyle.Top,Height=55,Font=new Font("Malgun Gothic",20,FontStyle.Bold),ForeColor=Color.FromArgb(30,55,83)};} Button Btn(string s,Action a,bool main=false){var b=new Button{Text=s,Height=42,FlatStyle=FlatStyle.Flat,BackColor=main?Color.FromArgb(45,174,160):Color.White,ForeColor=main?Color.White:Color.FromArgb(40,78,118),Font=new Font("Malgun Gothic",9,FontStyle.Bold)};b.FlatAppearance.BorderColor=main?b.BackColor:Color.FromArgb(190,210,230);b.Click+=(o,e)=>a();return b;}
  void ShowHome(){var wrap=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3};wrap.RowStyles.Add(new RowStyle(SizeType.Absolute,85));wrap.RowStyles.Add(new RowStyle(SizeType.Percent,100));wrap.RowStyles.Add(new RowStyle(SizeType.Absolute,55));wrap.Controls.Add(Title("작업실"),0,0);var listCard=Card();roomList=new ListBox{Dock=DockStyle.Fill,Font=new Font("Malgun Gothic",11),BorderStyle=BorderStyle.None};roomList.Items.AddRange(rooms.Cast<object>().ToArray());roomList.DoubleClick+=(s,e)=>OpenSelected();listCard.Controls.Add(roomList);wrap.Controls.Add(listCard,0,1);var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.LeftToRight};var create=Btn("+ 작업실 생성",CreateRoom,true);create.Width=160;var open=Btn("작업실 입장",OpenSelected);open.Width=140;buttons.Controls.Add(create);buttons.Controls.Add(open);wrap.Controls.Add(buttons,0,2);SetPage(wrap);}
  Panel Card(){return new Panel{Dock=DockStyle.Fill,BackColor=Color.White,Padding=new Padding(16),BorderStyle=BorderStyle.FixedSingle};}
  void CreateRoom(){var n=Microsoft.VisualBasic.Interaction.InputBox("작업실 이름을 입력하세요.","작업실 생성","");if(String.IsNullOrWhiteSpace(n))return;var room=new Room{Id=Guid.NewGuid().ToString("N"),Name=n.Trim(),Theme="이 캐릭터가 주제에 맞게 움직이는 고품질 TikTok 3D 애니메이션",Photo=""};rooms.Add(room);SaveRooms();current=room;ShowWorkspace();}
  void OpenSelected(){var x=roomList==null?null:roomList.SelectedItem as Room;if(x==null){MessageBox.Show("입장할 작업실을 선택하세요.");return;}current=x;ShowWorkspace();}
  void ShowWorkspace(){var all=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,RowCount=2};all.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,290));all.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));all.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,245));all.RowStyles.Add(new RowStyle(SizeType.Absolute,66));all.RowStyles.Add(new RowStyle(SizeType.Percent,100));var back=Btn("← 작업실 목록",ShowHome);back.Width=130;var head=new FlowLayoutPanel{Dock=DockStyle.Fill};head.Controls.Add(back);head.Controls.Add(new Label{Text=current.Name,AutoSize=true,Margin=new Padding(20,9,0,0),Font=new Font("Malgun Gothic",17,FontStyle.Bold),ForeColor=Color.FromArgb(30,55,83)});all.SetColumnSpan(head,3);all.Controls.Add(head,0,0);all.Controls.Add(Settings(),0,1);all.Controls.Add(Result(),1,1);all.Controls.Add(Archive(),2,1);SetPage(all);}
  Control Settings(){var c=Card();var f=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};f.Controls.Add(L("캐릭터 기준 사진"));photo=new PictureBox{Size=new Size(230,150),SizeMode=PictureBoxSizeMode.Zoom,BackColor=Color.FromArgb(242,246,250)};f.Controls.Add(photo);photoLabel=new Label{Width=240,Height=25,ForeColor=Color.FromArgb(100,116,139)};f.Controls.Add(photoLabel);var attach=Btn("사진 첨부",Attach);attach.Width=230;f.Controls.Add(attach);f.Controls.Add(L("작업실 주제"));theme=new TextBox{Multiline=true,Width=230,Height=80,Text=current.Theme,BackColor=Color.FromArgb(250,252,255)};f.Controls.Add(theme);f.Controls.Add(L("직접 프롬프트 입력 · 선택"));directPrompt=new TextBox{Multiline=true,Width=230,Height=95,PlaceholderText="직접 넣고 싶은 장면·행동·카메라 지시를 입력하세요",BackColor=Color.FromArgb(250,252,255)};f.Controls.Add(directPrompt);var save=Btn("작업실 설정 저장",SaveCurrent);save.Width=230;f.Controls.Add(save);var gen=Btn("완성 프롬프트 만들기",()=>{var foodMode=IsFoodVideoRoom();if(foodMode)Generate();else GenerateGeneric();if(foodMode)result.Text=FoodMasterRules()+result.Text;if(!String.IsNullOrWhiteSpace(directPrompt.Text))result.Text="[사용자 직접 프롬프트 지시]\r\nApply this instruction consistently across the entire video: "+directPrompt.Text.Trim()+"\r\n\r\n"+result.Text;if(!String.IsNullOrWhiteSpace(result.Text))SaveArchive();},true);gen.Width=230;f.Controls.Add(gen);LoadPhoto();c.Controls.Add(f);return c;}
  Label L(string x){return new Label{Text=x,Width=235,Height=26,Margin=new Padding(0,8,0,1),Font=new Font("Malgun Gothic",9,FontStyle.Bold),ForeColor=Color.FromArgb(51,65,85)};}
  void LoadPhoto(){photo.Image=null;photoLabel.Text=String.IsNullOrWhiteSpace(current.Photo)?"사진을 첨부해 주세요":Path.GetFileName(current.Photo);if(File.Exists(current.Photo))try{photo.Image=Image.FromFile(current.Photo);}catch{}}
  void Attach(){using(var d=new OpenFileDialog{Title="이 작업실의 캐릭터 기준 사진",Filter="이미지 파일|*.png;*.jpg;*.jpeg;*.webp"}){if(d.ShowDialog()!=DialogResult.OK)return;current.Photo=d.FileName;SaveRooms();LoadPhoto();}}
  void SaveCurrent(){current.Theme=theme.Text.Trim();SaveRooms();}
  Control Result(){var c=Card();result=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Font=new Font("Consolas",9),BackColor=Color.FromArgb(250,252,255),BorderStyle=BorderStyle.FixedSingle};c.Controls.Add(result);var revisionPanel=new Panel{Dock=DockStyle.Bottom,Height=100};revision=new TextBox{Multiline=true,Height=53,Dock=DockStyle.Top,PlaceholderText="수정 사항 입력: 예) 3장면을 더 귀엽게, 배경을 밤으로"};revisionPanel.Controls.Add(revision);var apply=Btn("수정 사항 반영",ApplyRevision,true);apply.Dock=DockStyle.Bottom;revisionPanel.Controls.Add(apply);c.Controls.Add(revisionPanel);c.Controls.Add(new Label{Text="완성 프롬프트",Dock=DockStyle.Top,Height=30,Font=new Font("Malgun Gothic",11,FontStyle.Bold)});var copy=Btn("영상 · BGM · 효과음 전체 복사",()=>{if(result.TextLength>0)Clipboard.SetText(result.Text);});copy.Dock=DockStyle.Top;c.Controls.Add(copy);return c;}
  Control Archive(){var c=Card();var grid=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3};grid.RowStyles.Add(new RowStyle(SizeType.Absolute,30));grid.RowStyles.Add(new RowStyle(SizeType.Percent,100));grid.RowStyles.Add(new RowStyle(SizeType.Absolute,142));grid.Controls.Add(new Label{Text="보관함 · 생성 시 자동 저장",Dock=DockStyle.Fill,Font=new Font("Malgun Gothic",10,FontStyle.Bold)},0,0);archive=new ListBox{Dock=DockStyle.Fill,BorderStyle=BorderStyle.None};archive.DoubleClick+=(s,e)=>{var x=archive.SelectedItem as Item;if(x!=null)result.Text=x.Text;};grid.Controls.Add(archive,0,1);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false};var save=Btn("완성 결과 보관",SaveArchive,true);save.Width=205;actions.Controls.Add(save);var update=Btn("수정 내용 저장",UpdateArchive);update.Width=205;actions.Controls.Add(update);var del=Btn("선택 제작물 삭제",DeleteArchive);del.Width=205;actions.Controls.Add(del);grid.Controls.Add(actions,0,2);c.Controls.Add(grid);LoadArchive();return c;}
  List<Item> GetArchive(){if(!File.Exists(ArchiveFile))return new List<Item>();return File.ReadAllLines(ArchiveFile).Select(x=>{var p=x.Split('|');return p.Length==3?new Item{Title=D(p[0]),Key=D(p[1]),Text=D(p[2])}:null;}).Where(x=>x!=null).ToList();}
  void LoadArchive(){if(archive==null)return;archive.Items.Clear();archive.Items.AddRange(GetArchive().Cast<object>().ToArray());}
  void DeleteArchive(){var x=archive.SelectedItem as Item;if(x==null)return;if(MessageBox.Show("선택한 제작물을 보관함에서 삭제할까요?","삭제",MessageBoxButtons.YesNo)==DialogResult.Yes){var left=GetArchive().Where(i=>i.Title!=x.Title).Select(i=>E(i.Title)+"|"+E(i.Key)+"|"+E(i.Text));File.WriteAllLines(ArchiveFile,left);LoadArchive();}}
  void UpdateArchive(){var x=archive.SelectedItem as Item;if(x==null||String.IsNullOrWhiteSpace(result.Text)){MessageBox.Show("보관함에서 수정할 제작물을 선택하세요.");return;}var all=GetArchive();var found=all.First(i=>i.Title==x.Title);found.Text=result.Text;File.WriteAllLines(ArchiveFile,all.Select(i=>E(i.Title)+"|"+E(i.Key)+"|"+E(i.Text)));LoadArchive();MessageBox.Show("수정 내용을 저장했습니다.");}
  string Pick(string[] a){return a[r.Next(a.Length)];}
  bool IsFoodVideoRoom(){return rooms.Count>0&&current.Id==rooms[0].Id;}
  string FoodMasterRules(){return "[음식 영상 전용 핵심 규칙]\r\nThis is a single-food transformation story. Select exactly ONE food for the entire video; never introduce a second food. The same food must retain its flavor/type, shape, size, color, topping, texture, remaining amount and bite marks across all four scenes.\r\n\r\nUse the attached reference character as the absolute fixed character model in every scene. Preserve its exact face, eye shape and color, proportions, costume/fur, species-defining features and tail count. Food-inspired changes must merge food properties into the original character rather than replace the character.\r\n\r\nDesign the transformation from 2–5 genuine food traits: form, softness/crispness, translucency, filling, surface, temperature, elasticity, decoration, and food-related magical particles. Do not do a simple color swap. Keep the setting, time of day, lighting, camera axis and character direction continuous.\r\n\r\n";}
  void ApplyRevision(){if(String.IsNullOrWhiteSpace(result.Text)||String.IsNullOrWhiteSpace(revision.Text)){MessageBox.Show("수정할 사항을 먼저 입력하세요.");return;}result.Text="[수정 반영 지시]\r\nApply this requested revision consistently to the title, all four scenes, camera, BGM and effects while preserving character continuity: "+revision.Text.Trim()+"\r\n\r\n"+result.Text;revision.Clear();}
  string Header(string title,string key,string intro){return "[이번 영상]\r\n\r\n제목 : "+title+"\r\n소개글 : "+intro+"\r\nKEY: "+key+"\r\n\r\n";}
  string CommonCharacter(){return "[공통 캐릭터 고정 프롬프트]\r\n첨부된 기준 이미지 속 캐릭터만 모든 장면의 주인공으로 사용한다. 동일한 얼굴 구조, 눈·귀·신체 비율, 종족 특징, 색감과 의상을 고정한다. 장면마다 다른 캐릭터로 재해석하지 않는다. high-end premium 3D animated film, cinematic soft lighting, detailed materials, expressive animation, vertical 9:16 composition, consistent character model.\r\n\r\n";}
  string Scene(string no,string name,string image,string motion,string behavior,string camera,string sound,string end){return "━━━━━━━━━━━━━━━━━━\r\n\r\n[장면 "+no+" — "+name+"]\r\n\r\n이미지 생성 프롬프트 :\r\n"+image+"\r\n\r\n영상 움직임 :\r\n"+motion+"\r\n\r\n캐릭터 행동 :\r\n"+behavior+"\r\n\r\n카메라 :\r\n"+camera+"\r\n\r\n사운드 · 효과음 :\r\n"+sound+"\r\n\r\n장면 마지막 상태 :\r\n"+end+"\r\n\r\n";}
  string Ending(string links){return "━━━━━━━━━━━━━━━━━━\r\n\r\n[BGM 프롬프트]\r\n전체 영상을 하나로 잇는 무보컬 시네마틱 BGM. 장면 1에서는 호기심 어린 가벼운 멜로디, 장면 2에서는 리듬감 있는 상호작용, 장면 3에서는 투명한 벨·패드·쉬머로 고조, 장면 4에서는 밝고 만족스러운 결말로 완성한다. 캐릭터 소리와 효과음을 가리지 않도록 낮은 믹스, 마지막 효과음 뒤 자연스럽게 루프 가능.\r\n\r\n[장면 연결]\r\n"+links+"\r\n\r\n[공통 네거티브 프롬프트]\r\ndifferent character, inconsistent face, character redesign, extra characters, human hands, extra limbs, malformed anatomy, duplicate features, sudden costume change, teleportation, jump cut, inconsistent background, inconsistent lighting, unrelated props, text, subtitles, captions, logo, watermark, UI, horror, gore.\r\n";}
  void GenerateGeneric(){SaveCurrent();if(String.IsNullOrWhiteSpace(current.Photo)){MessageBox.Show("먼저 캐릭터 기준 사진을 첨부하세요.");return;}var topic=String.IsNullOrWhiteSpace(current.Theme)?"귀엽고 완성도 높은 3D 판타지 애니메이션":current.Theme.Trim();var place=Pick(places);var moment=Pick(new[]{"빛나는 재료와 도구를 발견하는 순간","작은 문제를 창의적으로 해결하는 순간","정성스럽게 무언가를 완성하는 순간","신비로운 장소를 탐험하는 순간","주제의 마법적 특징을 체험하는 순간"});var key="theme/"+topic+"/"+place+"/"+moment;var title=current.Name+" — "+topic;result.Text=Header(title,key,"첨부 캐릭터가 ‘"+topic+"’이라는 작업실 주제를 따라 하나의 짧고 완결된 이야기를 경험하는 TikTok용 4장면 3D 애니메이션.")+"[전체 연출 콘셉트]\r\n주제 ‘"+topic+"’을 캐릭터의 행동, 소품, 공간, 빛과 효과로 자연스럽게 시각화한다. 단순한 설명 영상이 아니라 발견 → 몰입 → 핵심 변화/완성 → 귀여운 엔딩의 서사를 만든다. 장소는 "+place+"이며 네 장면 동안 시간대와 조명, 공간 구조를 유지한다.\r\n\r\n[최종 장면 디자인]\r\n캐릭터의 원래 정체성은 유지하고, ‘"+topic+"’에서 파생한 질감·색·소품·마법 이펙트만 절제되게 더한다. 화면을 가리는 과도한 장식은 피하고 얼굴과 행동이 항상 읽히게 한다.\r\n\r\n"+CommonCharacter()+Scene("1","주제 발견 / 시작","첨부 기준 이미지와 동일한 캐릭터가 "+place+"에서 ‘"+topic+"’과 관련된 핵심 소품 또는 단서를 발견한다. 캐릭터는 아직 원래 모습이며, 공간의 대표 질감과 색을 선명하게 보여준다. premium 3D animated fantasy short, vertical 9:16.","걸어오다가 단서를 발견하고 멈춘 뒤 천천히 가까이 다가간다.","눈빛이 호기심으로 바뀌고 고개를 살짝 기울여 자세히 살핀다.","캐릭터와 핵심 단서를 함께 담는 낮은 중간 거리, 접근에 맞춰 아주 느린 줌인.","공간의 은은한 앰비언스, 가벼운 발소리, 발견 순간 작은 반짝임.","캐릭터가 핵심 단서 바로 앞에서 다음 행동을 결심한다.")+Scene("2","직접 행동 / 몰입","장면 1과 완전히 같은 장소·조명·카메라 축. 동일한 캐릭터가 ‘"+topic+"’을 실제 행동으로 경험하며 "+moment+". 손/발/도구와 소품의 접촉이 물리적으로 자연스럽고 결과가 눈에 보인다.","작고 읽기 쉬운 한 번의 핵심 행동을 완수하고 반응한다.","집중한 표정에서 놀람 또는 즐거움으로 부드럽게 변화한다.","얼굴과 행동 지점을 중심으로 부드럽게 클로즈업, 장면 1의 축을 유지.","행동에 맞는 촉감 효과음, 짧은 캐릭터 리액션, BGM 리듬이 조금 더 살아난다.","핵심 행동의 결과가 남아 장면 3의 출발점이 된다.")+Scene("3","핵심 전개 / 변화","동일한 캐릭터와 공간에서 ‘"+topic+"’의 가장 매력적인 시각적 순간이 펼쳐진다. 장면 2의 결과가 캐릭터 주변 또는 소품에 자연스럽게 확장되고, 주제와 무관한 효과는 넣지 않는다.","결과가 단계적으로 펼쳐지고 캐릭터가 그것을 따라 움직인다.","자신의 앞발·도구·주변 변화를 확인한 뒤 기뻐하거나 신기해한다.","얼굴에서 행동 지점, 주변 변화로 천천히 이동한 뒤 전체를 보여준다.","테마에 맞는 맑은 효과음과 섬세한 쉬머, 음악이 가장 기분 좋게 고조된다.","변화 또는 완성이 거의 끝난 상태에서 캐릭터가 카메라 쪽으로 시선을 돌린다.")+Scene("4","완성 / 루프형 엔딩","‘"+topic+"’의 완성된 결과와 동일한 캐릭터를 선명하게 보여준다. 캐릭터는 원래의 정체성을 유지하면서 주제에 맞는 작은 시각적 포인트와 함께 만족스러운 포즈를 취한다. clean premium 3D TikTok ending, no text.","완성 결과를 확인한 뒤 가볍게 점프하거나 작은 제스처로 엔딩을 만든다.","카메라를 보고 귀여운 표정과 한 번의 명확한 마무리 행동을 한다.","살짝 줌아웃해 결과를 보여준 뒤 얼굴로 천천히 다시 접근.","밝은 마무리 효과음, 작은 만족스러운 캐릭터 소리, 마지막 한 음으로 루프 연결.","첫 장면의 호기심 어린 시선으로 자연스럽게 돌아갈 수 있는 짧은 홀드.")+Ending("장면 1 → 2 : 발견한 단서에 손/발을 뻗는 동작을 그대로 이어간다.\r\n장면 2 → 3 : 행동의 결과가 사라지지 않고 자연스럽게 확장된다.\r\n장면 3 → 4 : 가장 큰 변화가 완성되며 캐릭터의 놀람이 기쁨으로 바뀌어 최종 포즈로 이어진다.");}
  void Generate(){SaveCurrent();if(String.IsNullOrWhiteSpace(current.Photo)){MessageBox.Show("먼저 캐릭터 기준 사진을 첨부하세요.");return;}var used=GetArchive().Select(x=>x.Key).ToHashSet();string place,raw,key;int n=0;do{place=Pick(places);raw=Pick(props);key="food/"+place+"/"+raw;n++;}while(used.Contains(key)&&n<50);var cut=raw.IndexOf(':');var food=cut<0?raw:raw.Substring(0,cut);var detail=cut<0?raw:raw.Substring(cut+1).Trim();var story=String.IsNullOrWhiteSpace(current.Theme)?"음식의 특징을 흡수해 귀엽고 자연스럽게 변신하는 판타지":current.Theme.Trim();var form="‘"+food+"’의 질감·형태·장식·맛 이미지를 원래 캐릭터의 털/피부/외곽선/주변 이펙트에 융합한 최종 디자인";result.Text=Header(current.Name+" — "+food+" 변신 이야기",key,"첨부 캐릭터가 "+food+" 한 종류를 경험하고, 그 음식의 진짜 특징을 흡수해 변신하는 4장면 TikTok 3D 애니메이션.")+"음식 : "+food+"\r\n음식 핵심 특징 : "+detail+"\r\n\r\n[전체 변신 콘셉트]\r\n첨부된 기준 이미지 속 캐릭터가 "+food+"을 먹은 뒤 음식의 특징을 흡수하여 "+form+"으로 변화한다. 단순 색상 변경이 아니라 음식의 질감, 표면, 부드러움/바삭함, 장식과 맛의 인상을 2~5가지 골라 신체와 효과에 자연스럽게 융합한다. 작업실 주제는 ‘"+story+"’이며, 캐릭터 자체가 음식 덩어리로 교체되지 않는다.\r\n\r\n[최종 변신 디자인]\r\n신체 : 원래 체형·얼굴·종족 특징을 유지하고 음식 특성에 맞는 미세한 질감 변화만 적용한다.\r\n표면·털 : "+food+"의 표면과 질감을 연상시키되 기본 캐릭터 색과 정체성을 가장 높은 비중으로 유지한다.\r\n장식·이펙트 : 음식에서 실제로 파생한 작은 입자, 빛, 향기 또는 장식만 사용하며 얼굴과 눈을 가리지 않는다.\r\n색감 : 음식 고유 색을 포인트로만 사용하며 네온·단순 색상 교체를 피한다.\r\n\r\n[음식 연속성 규칙]\r\n네 장면 전체에서 음식은 반드시 ‘"+food+"’ 단 하나만 사용한다. 소품의 형태·크기·색·토핑·질감·남은 양을 고정하고, 2장면에서 생긴 실제 한입 자국은 3·4장면까지 정확히 유지한다.\r\n\r\n"+CommonCharacter()+Scene("1","음식 발견 / 변신 0%","첨부 기준 이미지와 동일한 캐릭터가 "+place+"의 테이블 위에 놓인 "+food+"을 발견한다. 음식은 "+detail+". 캐릭터는 완전히 원래 모습이고 변신 이펙트·추가 장식은 아직 없다.","걸어가다가 음식을 발견하고 멈춘 뒤 코 또는 시선을 음식 가까이 가져간다.","호기심으로 눈을 반짝이고 고개를 살짝 기울인다.","캐릭터와 음식이 함께 보이는 낮은 중간 거리, 아주 느린 줌인.","부드러운 발소리, 냄새를 맡는 작은 소리, 발견 순간 맑은 반짝임.","음식 바로 앞에서 먹기 직전의 자세. 변신 0%.")+Scene("2","한입 섭취 / 변신 10~20%","장면 1과 동일한 장소·조명. 동일 캐릭터가 같은 "+food+"에 입을 대고 실제로 한입 베어 문다. 입과 음식이 정확히 접촉하며, 음식에는 작고 명확한 한입 자국이 남는다. 음식 특성에서 나온 아주 미세한 변화만 입 주변에 시작된다.","한입을 베어 먹고 두세 번 귀엽게 씹은 뒤 삼킨다.","맛을 느끼며 눈을 잠깐 감았다가 놀라서 다시 뜬다.","얼굴과 음식 접촉 지점을 부드럽게 클로즈업, 장면 1 카메라 축 유지.","음식 질감에 맞는 ASMR 한입 소리, 씹는 소리, 삼키는 순간 작은 마법음.","한입 자국이 남고 음식 영향의 작은 입자만 보인다. 변신 약 15%.")+Scene("3","본격 변신 / 변신 40~60%","동일한 장소에서 "+food+"의 특징이 입 주변에서 몸과 원래 종족 특징으로 점진적으로 퍼진다. "+detail+"의 특성을 시각화하되 원래 캐릭터의 얼굴과 정체성을 유지한다. 음식은 장면 2의 한입 자국과 남은 양을 그대로 유지한다.","작은 파동이 지나간 부위만 순서대로 변화하고, 캐릭터가 자신의 변화를 확인한다.","앞발 또는 신체 일부를 보고 놀란 뒤, 변한 특징을 조심스럽게 만져 본다.","얼굴 → 변화 부위 → 전신을 따라 부드럽게 이동하고 전체를 보여준다.","섬세한 마법 쉬머, 음식 질감에 맞는 연속 효과, 작은 입자 소리와 고조되는 BGM.","완성 디자인의 절반 이상이 드러나고 캐릭터가 다음 변화를 기다린다. 변신 약 55%.")+Scene("4","완전 변신 / 변신 100%","첨부 기준 이미지의 동일 캐릭터가 "+food+"의 특성을 완전히 흡수한 최종 모습. "+form+". 원래 얼굴·비율·종족 특징은 그대로, 음식 유래 포인트는 정교하고 절제되게 표현한다. 동일한 음식과 한입 자국은 화면 속에 연속성 있게 남아 있다.","마지막 변화가 부드럽게 완성되고 캐릭터가 가볍게 점프한 뒤 귀여운 포즈를 취한다.","완성된 모습을 확인하고 카메라를 향해 고개를 살짝 기울이거나 앞발을 든다.","완성 순간 살짝 줌아웃해 전체 실루엣을 보여주고 얼굴로 다시 접근.","완성 효과음, 음식 특성에 맞는 맑고 기분 좋은 입자음, 점프 착지와 마지막 작은 캐릭터 소리.","작은 음식 유래 입자가 코앞에서 사라지며 눈을 한 번 깜빡이는 루프형 엔딩. 변신 100%.")+Ending("장면 1 → 2 : 음식을 맡던 동작이 그대로 한입으로 이어진다.\r\n장면 2 → 3 : 삼킨 직후 입 주변의 음식 유래 입자가 첫 변화 부위에 닿으며 변신을 시작한다.\r\n장면 3 → 4 : 변화 파동이 마지막 부위까지 도달하고 캐릭터의 놀란 표정이 기쁜 표정으로 바뀌며 점프한다.");}
  void SaveArchive(){if(result==null||String.IsNullOrWhiteSpace(result.Text))return;var title=Read("제목 :");var key=Read("KEY:");File.AppendAllText(ArchiveFile,E(title)+"|"+E(key)+"|"+E(result.Text)+Environment.NewLine);LoadArchive();}
  void CheckForUpdate(){try{using(var wc=new WebClient()){wc.Headers.Add("User-Agent","Creature-Animation-Studio");var json=wc.DownloadString("https://api.github.com/repos/god199683/animation/releases/latest");var match=Regex.Match(json,"\\\"browser_download_url\\\":\\\"([^\\\"]*CreatureAnimationStudio\\.exe)\\\"");if(!match.Success)return;var next=Path.Combine(Path.GetTempPath(),"CreatureAnimationStudio-update.exe");wc.DownloadFile(match.Groups[1].Value.Replace("\\/","/"),next);var current=Application.ExecutablePath;if(new FileInfo(next).Length==new FileInfo(current).Length){File.Delete(next);return;}var script=Path.Combine(Path.GetTempPath(),"CreatureAnimationStudio-update.cmd");File.WriteAllText(script,"@echo off\r\ntimeout /t 2 /nobreak >nul\r\ncopy /y \""+next+"\" \""+current+"\"\r\nstart \"\" \""+current+"\"\r\ndel \"%~f0\"");Process.Start(new ProcessStartInfo(script){UseShellExecute=true,WindowStyle=ProcessWindowStyle.Hidden});Close();}}catch{}}
  string Read(string k){var i=result.Text.IndexOf(k);if(i<0)return DateTime.Now.ToString("yyyy-MM-dd HH:mm");var e=result.Text.IndexOf('\n',i);return result.Text.Substring(i+k.Length,(e<0?result.Text.Length:e)-i-k.Length).Trim();}
 }
